import math
import re
import subprocess
import sys
from collections import Counter
from datetime import date
from pathlib import Path

WORD = re.compile(r"[a-z0-9_]+")
K1, B = 1.2, 0.75
DAYS = {"30d": 30, "90d": 90, "180d": 180, "365d": 365}


def tokens(text: str) -> list[str]:
    return WORD.findall(text.lower())


def frontmatter(text: str) -> dict[str, str]:
    head = text.split("---")[1]
    return dict(line.split(": ", 1) for line in head.splitlines() if ": " in line and not line.startswith(" "))


def bm25(query: str, docs: dict[str, list[str]]) -> dict[str, float]:
    n = len(docs)
    avg_len = sum(len(words) for words in docs.values()) / n
    df = Counter(word for words in docs.values() for word in set(words))
    scores = {}
    for path, words in docs.items():
        tf = Counter(words)
        score = 0.0
        for q in set(tokens(query)):
            if q not in tf:
                continue
            idf = math.log(1 + (n - df[q] + 0.5) / (df[q] + 0.5))
            score += idf * tf[q] * (K1 + 1) / (tf[q] + K1 * (1 - B + B * len(words) / avg_len))
        scores[path] = score
    return scores


def effective(meta: dict[str, str]) -> str:
    age = (date.today() - date.fromisoformat(meta["reviewed"])).days
    return "low" if age > 2 * DAYS[meta["review_every"]] else meta["confidence"]


def main() -> None:
    kb, query = Path(sys.argv[1]), sys.argv[2]
    sha = subprocess.run(["git", "-C", kb, "rev-parse", "--short", "HEAD"], capture_output=True, text=True).stdout.strip()
    pages = {str(p.relative_to(kb)): p.read_text() for p in sorted(kb.rglob("*.md"))}
    scores = bm25(query, {path: tokens(text) for path, text in pages.items()})
    for path, score in sorted(scores.items(), key=lambda item: -item[1])[:5]:
        if score > 0:
            meta = frontmatter(pages[path])
            print(f"rnd-kb/{path}@{sha}  {meta['title']}  ({effective(meta)}, reviewed {meta['reviewed']})  {score:.2f}")


if __name__ == "__main__":
    main()
